      sortDirection[field] = !sortDirection[field];
      currentQuotes.sort((a, b) => {
        let valA = a[field];
        let valB = b[field];
        if (typeof valA === 'string') {
          return sortDirection[field] ? valA.localeCompare(valB) : valB.localeCompare(valA);
        }
        return sortDirection[field] ? valA - valB : valB - valA;
      });
      renderTable(currentQuotes);
    }

    function filterQuotes() {
      const query = document.getElementById('search-input').value.toLowerCase().trim();
      if (!query) {
        currentQuotes = [...allQuotes];
      } else {
        currentQuotes = allQuotes.filter(q => 
          q.id.toLowerCase().includes(query) || 
          q.carrier.toLowerCase().includes(query) || 
          q.route.toLowerCase().includes(query) ||
          q.sheet.toLowerCase().includes(query)
        );
      }
      renderTable(currentQuotes);
    }

