"import re, glob

# Check header and footer brand snippets across all templates
templates = glob.glob('templates/**/*.html', recursive=True) + glob.glob('templates/*.html')

for t in sorted(templates):
    with open(t, 'r', encoding='utf-8') as f:
        content = f.read()
    print(f"\n--- {t} ---")
    headers = re.findall(r'<header[^>]*>.*?</header>', content, re.DOTALL)
    for h in headers:
        m = re.findall(r'<a[^>]*class="[^"]*flex items-center[^"]*"[^>]*>.*?</a>', h, re.DOTALL)
        if m:
